package com.biglybt.core.dht.db.impl;
import com.biglybt.core.dht.*;
import com.biglybt.core.dht.control.*;
import com.biglybt.core.dht.router.*;
import com.biglybt.core.dht.transport.*;
import com.biglybt.core.util.*;
import java.lang.reflect.*;
import java.net.*;
import java.nio.file.*;
import java.util.*;
public final class OriginalCacheRepublish extends DHTDBImpl {
 static final int PERIOD=600000;
 static Object defaults(Method m){Class<?> t=m.getReturnType();if(t==boolean.class)return false;if(t==byte.class)return (byte)0;if(t==short.class)return (short)0;if(t==int.class)return 0;if(t==long.class)return 0L;return null;}
 static <T>T proxy(Class<T> type,InvocationHandler h){return type.cast(java.lang.reflect.Proxy.newProxyInstance(type.getClassLoader(),new Class<?>[]{type},h));}
 static DHTLogger logger(){return proxy(DHTLogger.class,(p,m,a)->defaults(m));}
 final byte[] localId=new byte[20];final List<Object> relayed=new ArrayList<>();int tokens=0,dead=0,refresh=0;boolean keep=true,tokenFails=false;
 final DHTTransportContact local,destination;
 OriginalCacheRepublish(){super(null,8*3600000,PERIOD,(byte)0,logger());localId[0]=1;local=contact(1);destination=contact(2);
  DHTRouter router=proxy(DHTRouter.class,(p,m,a)->{switch(m.getName()){case "getID":return localId;case "isID":return Arrays.equals(localId,(byte[])a[0]);case "getK":return 20;case "refreshIdleLeaves":refresh++;return null;case "contactDead":dead++;return null;default:return defaults(m);}});
  DHTTransport transport=proxy(DHTTransport.class,(p,m,a)->m.getName().equals("getLocalContact")?local:defaults(m));
  DHTControl control=proxy(DHTControl.class,(p,m,a)->{switch(m.getName()){case "getRouter":return router;case "getTransport":return transport;case "getClosestKContactsList":return keep?Arrays.asList(local,destination):Arrays.asList(destination);case "putDirectEncodedKeys":DHTTransportValue[][] values=(DHTTransportValue[][])a[2];for(DHTTransportValue[] set:values)for(DHTTransportValue v:set){Map<String,Object> r=new TreeMap<>();r.put("version",(long)v.getVersion());r.put("payload",v.getValue());r.put("origin",v.getOriginator().getID());r.put("sender",((DHTDBValueImpl)v).getSender().getID());r.put("flags",(long)(v.getFlags()&255));r.put("life",(long)(v.getLifeTimeHours()&255));r.put("rep",(long)v.getReplicationControl());relayed.add(r);}return null;default:return defaults(m);}});setControl(control);
 }
 DHTTransportContact contact(int number){byte[] id=new byte[20];id[0]=(byte)number;InetSocketAddress addr=new InetSocketAddress("127.0.0."+number,8000+number);return proxy(DHTTransportContact.class,(p,m,a)->{switch(m.getName()){case "getID":return id;case "getAddress":case "getTransportAddress":case "getExternalAddress":return addr;case "getBloomKey":return addr.getAddress().getAddress();case "getProtocolVersion":return (byte)55;case "hashCode":return number;case "equals":return p==a[0];case "sendFindNode":tokens++;if(tokenFails)((DHTTransportReplyHandler)a[0]).failed((DHTTransportContact)p,new Exception("Generated token failure"));else ((DHTTransportReplyHandler)a[0]).findNodeReply((DHTTransportContact)p,new DHTTransportContact[0]);return null;default:return defaults(m);}});}
 @SuppressWarnings("unchecked") Map<HashWrapper,DHTDBMapping> mappings()throws Exception{Field f=DHTDBImpl.class.getDeclaredField("stored_values");f.setAccessible(true);return (Map<HashWrapper,DHTDBMapping>)f.get(this);}
 static Map<String,Object> run(String name,int div,boolean keep,boolean tokenFails,int... kinds)throws Exception{
  System.err.println("ORIGINAL_CASE "+name);OriginalCacheRepublish db=new OriginalCacheRepublish();db.keep=keep;db.tokenFails=tokenFails;try{long now=System.currentTimeMillis();byte[] rawKey=new byte[20];rawKey[0]=42;HashWrapper key=new HashWrapper(rawKey);DHTDBMapping mapping=new DHTDBMapping(db,key,false);List<DHTDBValueImpl> values=new ArrayList<>();List<Object> inputs=new ArrayList<>();
   for(int i=0;i<kinds.length;i++){int kind=kinds[i];boolean local=kind==0;byte rep=(byte)((kind==4||kind==5||kind==8)?0x27:kind==6?0:-1);long stored=(kind==2||kind==5)?now-1000:(kind==3||kind==8)?now+3600000:kind==7?Long.MIN_VALUE:now-PERIOD-60000;DHTTransportContact origin=local?db.local:db.contact(i+3);DHTDBValueImpl value=new DHTDBValueImpl(now-1000,new byte[]{(byte)(i+10)},i+10,origin,origin,local,0x21,72,rep);mapping.add(value);value.setStoreTime(stored);values.add(value);Map<String,Object> input=new TreeMap<>();input.put("local",local?1L:0L);input.put("rep",(long)rep);input.put("stored",stored);inputs.add(input);}
   Field field=DHTDBMapping.class.getDeclaredField("diversification_state");field.setAccessible(true);field.setByte(mapping,(byte)div);db.mappings().put(key,mapping);db.addToPrefixMap(mapping);int[] counts=db.republishCachedMappings();List<Object> reset=new ArrayList<>();for(int i=0;i<values.size();i++)if(values.get(i).getStoreTime()!=((Number)((Map<?,?>)inputs.get(i)).get("stored")).longValue())reset.add((long)i);List<Object> versions=new ArrayList<>();for(Object item:db.relayed)versions.add(((Number)((Map<?,?>)item).get("version")).longValue()-10);Map<String,Object> result=new TreeMap<>();result.put("name",name);result.put("now",now);result.put("period",(long)PERIOD);result.put("div",(long)div);result.put("input",inputs);result.put("due",versions);result.put("reset",reset);result.put("kept",db.mappings().containsKey(key)?1L:0L);result.put("tokens",(long)db.tokens);result.put("dead",(long)db.dead);result.put("refresh",(long)db.refresh);result.put("relayed",db.relayed);result.put("values_published",(long)counts[0]);result.put("keys_published",(long)counts[1]);result.put("operations",(long)counts[2]);return result;
  }finally{db.destroy();}
 }
 public static void main(String[] args)throws Exception{List<Object> cases=new ArrayList<>();cases.add(run("empty",1,true,false));cases.add(run("local-only",1,true,false,0));cases.add(run("due",1,true,false,1));cases.add(run("recent",1,true,false,2));cases.add(run("future",1,true,false,3));cases.add(run("explicit-only",1,true,false,4));cases.add(run("zero-factor",1,true,false,6));cases.add(run("explicit-future",1,true,false,8));cases.add(run("local-and-explicit-due",1,true,false,0,4));cases.add(run("local-and-due",1,true,false,0,1));cases.add(run("default-recent-explicit-due",1,true,false,2,4));cases.add(run("default-due-explicit-due",1,true,false,1,4));cases.add(run("default-due-explicit-recent",1,true,false,1,5));cases.add(run("frequency-diversified",2,true,false,1,3));cases.add(run("size-diversified",3,true,false,1,3));cases.add(run("last-forward-before-drop",1,false,false,1));cases.add(run("survey-only-drop",1,false,false,4));cases.add(run("token-failure",1,true,true,1));cases.add(run("wrapped-long-age",1,true,false,7));Map<String,Object> out=new TreeMap<>();out.put("cases",cases);Files.write(Paths.get(args[0]),BEncoder.encode(out));System.out.println("ORIGINAL_CACHE_REPUBLISH cases="+cases.size());com.biglybt.core.security.SESecurityManager.exitVM(0);}
}
